package binlogviz

import (
	"encoding/json"
	"strings"
	"testing"

	"binlogviz/internal/analyzer"
)

// mysql-8.4.11-ddlfilter-drop-multi.binlog is a real server file whose query is
// DROP TABLE `rn`.`z`,`rn`.`t1` /* generated by server */.
func TestAnalyzeServerMultiDropNamesEachTable(t *testing.T) {
	forceEnglishRuntimeOutput(t)
	fixture := mustFixturePath(t, "mysql-8.4.11-ddlfilter-drop-multi.binlog")
	for _, format := range []string{"json", "text", "markdown", "html"} {
		stdout, stderr, err := captureStdoutStderrRun(t, func() error {
			return runAnalysis([]string{fixture}, analyzer.DefaultOptions(), format)
		})
		if err != nil {
			t.Fatalf("%s: %v stderr=%s", format, err, stderr)
		}
		if strings.Contains(stdout, "z`,`rn.t1") {
			t.Fatalf("%s report kept the split name:\n%s", format, stdout)
		}
		if format == "json" {
			continue
		}
		if !strings.Contains(stdout, "rn.z") || !strings.Contains(stdout, "rn.t1") {
			t.Fatalf("%s report missing a dropped table:\n%s", format, stdout)
		}
	}

	stdout, stderr, err := captureStdoutStderrRun(t, func() error {
		return runAnalysis([]string{fixture}, analyzer.DefaultOptions(), "json")
	})
	if err != nil {
		t.Fatalf("json: %v stderr=%s", err, stderr)
	}
	var doc struct {
		Tables []struct {
			Schema string `json:"schema"`
			Table  string `json:"table"`
		} `json:"tables"`
		Diagnostics struct {
			DDLEvents []struct {
				Schema    string `json:"schema"`
				Table     string `json:"table"`
				Operation string `json:"operation"`
			} `json:"ddl_events"`
		} `json:"diagnostics"`
	}
	if err := json.Unmarshal([]byte(stdout), &doc); err != nil {
		t.Fatalf("decode: %v", err)
	}
	drops := map[string]int{}
	for _, event := range doc.Diagnostics.DDLEvents {
		if event.Operation != "DROP TABLE" {
			continue
		}
		if strings.Contains(event.Schema, "`") || strings.Contains(event.Table, "`") {
			t.Fatalf("ddl schema=%q table=%q", event.Schema, event.Table)
		}
		drops[event.Schema+"."+event.Table]++
	}
	if drops["rn.z"] != 1 || drops["rn.t1"] != 1 || len(drops) != 2 {
		t.Fatalf("drop targets = %v", drops)
	}
	seen := map[string]bool{}
	for _, table := range doc.Tables {
		if strings.Contains(table.Schema, "`") || strings.Contains(table.Table, "`") {
			t.Fatalf("table schema=%q table=%q", table.Schema, table.Table)
		}
		seen[table.Schema+"."+table.Table] = true
	}
	if !seen["rn.z"] || !seen["rn.t1"] {
		t.Fatalf("tables = %v", seen)
	}
}

func TestFlashbackServerMultiDropListsEveryTable(t *testing.T) {
	forceEnglishRuntimeOutput(t)
	fixture := mustFixturePath(t, "mysql-8.4.11-ddlfilter-drop-multi.binlog")
	code, stdout, stderr := runRoot(t, "--error-format", "json", "flashback", "-q", fixture)
	if code != 6 || stdout != "" {
		t.Fatalf("exit %d stdout %q\n%s", code, stdout, stderr)
	}
	var body struct {
		Error struct {
			Kind    string         `json:"kind"`
			Message string         `json:"message"`
			Details map[string]any `json:"details"`
		} `json:"error"`
	}
	if err := json.Unmarshal([]byte(lastJSONLine(stderr)), &body); err != nil {
		t.Fatalf("json: %v\n%s", err, stderr)
	}
	if body.Error.Kind != "refused" || body.Error.Details["reason"] != "ddl_in_range" || body.Error.Details["table"] != "rn.z, rn.t1" {
		t.Fatalf("details %+v message %s", body.Error.Details, body.Error.Message)
	}
	if !strings.Contains(body.Error.Message, "rn.z, rn.t1") || !strings.Contains(body.Error.Message, "DROP TABLE `rn`.`z`,`rn`.`t1`") || !strings.Contains(body.Error.Message, "flashback does not undo schema changes") {
		t.Fatalf("message %s", body.Error.Message)
	}
}
